<template>
	<view class="container">
		<u-loading-page :loading="true" v-if="load" fontSize="28rpx" />
		<block v-else>
		<scroll-view scroll-y="true" class="scroll" :style="{'height':`calc(100% - 110rpx - ${safe_bot}px)`}">
			<view class="cart-container">
				<view class="confirm-address order-group" @click="toAddress">
					<image src="@/static/common/dingwei.png" mode="widthFix" class="icon-img"/>
					<view class="confirm-address-right" v-if="Object.keys(user_address).length>0">
						<view class="confirm-address-consignee">
							<text class="consignee-text">{{user_address.consignee}}</text>
							<text class="mobile-text">{{user_address.mobile}}</text>
						</view>
						<text class="detail-text">{{user_address.province+user_address.city+user_address.district+user_address.address}}</text>
					</view>
					<view class="confirm-address-add" v-else>添加收货地址</view>
					<u-icon name="arrow-right" color="#353535" size="16" class="arrow-right" />
				</view>
				<view class="goods-items order-group">
					<view class="goods-item" v-for="(child,childIndex) in goods" :key="childIndex">
						<image :src="getFullUrl(child.goods_img)" class="goods-img" mode="aspectFit"/>
						<view class="goods-item-right">
							<view class="goods-name">{{child.goods_name}}</view>
							<view class="goods-spec">已选:{{child.item_name?child.item_name:'无'}}</view>
							<view class="goods-bot-box">
								<view class="goods-price">
									<text>¥</text>
									<text class="jiage">{{child.goods_price}}</text>
								</view>
								<view class="goods-num-box">x{{child.goods_num}}</view>
							</view>
						</view>
					</view>
					<view class="note-row">
						<text>用户备注</text>
						<u-input border="none"  placeholder="请输入用户备注(选填)"
							placeholderClass="placeholder28" type="text" fontSize="28rpx" clearable v-model="user_note" />
					</view>
				</view>
				<view class="order-rows order-group">
					<view class="order-row">
						<text>订单总额</text>
						<text>¥{{total_amount}}</text>
					</view>
				</view>
				<view class="pay-container order-group">
					<view class="title">支付方式</view>
					<view class="pay-rows">
						<view class="pay-row" v-for="(item,index) in pay_list" :key="index" @click="changePay(item)">
							<image :src="item.pay_img" mode="widthFix" class="zf-img"/>
							<text>{{item.pay_name}}</text>
							<image 
							:src="item.pay_code==pay_code?'/static/common/checkbox_select.png':'/static/common/checkbox_unselect.png'"
							 mode="widthFix" 
							 class="icon-img"/>
						</view>
					</view>
				</view>
				<view style="height: 20rpx;"></view>
			</view>
		</scroll-view>
		<view class="cart-bottom" v-if="goods.length>0">
			<view class="bottom-info">
				<view class="center">合计</view>
				<view class="amount">
					<text>¥</text>
					<text class="total-amount">{{total_amount}}</text>
				</view>
				<button class="submit-btn" @click="cart_tj('yes')" :disabled="submitDisabled">立即支付</button>
			</view>
			<view :style="{'height':safe_bot + 'px'}"></view>
		</view>
		</block>
	</view>
</template>

<script>
	var _this;
	export default {
		data() {
			return {
				goods_id: 0,
				item_id: 0,
				goods_num: 0,
				order_id: 0,
				action: '',
				user_note: '',
				submitDisabled:false,
				goods:[],
				user_address:{},
				pay_list:[],
				pay_code:'',
				balance:0,
				safe_bot:0
			};
		},
		methods: {
			async cart_tj(act = ''){
				const params = {
					goods_id: _this.goods_id,
					item_id: _this.item_id,
					goods_num: _this.goods_num,
					order_id: _this.order_id || 0,
				}
				// #ifdef MP-WEIXIN
				let openid = uni.getStorageSync('openid')
				params.is_xcx = 1
				params.openid = openid
				// #endif
				if(_this.action){
					params.action = _this.action
				}
				if (act) {
					params.act = act
					params.pay_code = _this.pay_code
					params.user_note = _this.user_note
					params.address_id = _this.user_address?.address_id || 0
					params.goods = _this.goods.map(item=>{
						return {
							goods_id:item.goods_id,
							goods_num:item.goods_num,
							item_id:item.item_id,
							id:item.id || 0,
						}
					})
					
					_this.submitDisabled = true
					setTimeout(()=>{
						_this.submitDisabled = false
					},2000)
				}
				const data = await _this.$post('port/add_order', params)
				if (data.code == -1) {
					_this.user_address = data.result.add || {}
					_this.goods = data.result.goods
					_this.pay_list = data.result.pay_list
					_this.pay_code = _this.pay_list[0]['pay_code']
					_this.balance = data.result.balance
					if (_this.load) {
						_this.load = false
					}
				} else if(data.code==-50){
					uni.requestPayment({
						provider: 'wxpay',
						timeStamp: data.result.timeStamp+'',
						nonceStr: data.result.nonceStr,
						package: data.result.package,
						signType: data.result.signType,
						paySign: data.result.sign,
						success(res) {
							console.log('success:' + JSON.stringify(res));
							_this.$u.toast('支付成功',()=>{
								_this.toNext('/pages/order/order-list?type=2',true)
							})
						},
						fail(err) {
							_this.$u.toast('支付失败',()=>{
								_this.toNext('/pages/order/order-list?type=1',true)
							})
							console.log('fail:' + JSON.stringify(err));
						}
					});
				}else if(data.code==20){
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}else if(data.code==10){
					uni.$u.toast(data.msg,()=>{
						_this.toNext(`/pages/order/order-list?type=0`,true)
					})
				}else {
					uni.$u.toast(data.msg)
				}
			},
			//查询订单支付状态
			async queryOrder(order_sn){
				let params = {
					order_sn
				}
				const data = await _this.$post('port/chaxun_order', params)
				if (data.code==200) {
					_this.toNext(`/pages/order/order-list?type=2`,true)
				} else if(data.code==100){
					_this.toNext(`/pages/order/order-list?type=1`,true)
				}else{
					uni.$u.toast(data.msg,()=>{
						_this.finish()
					})
				}
			},
			changeNum(item, step) {
				var number = item.goods_num + step
				if (step < 0) {
					if (number < 1) {
						return
					}
					item.goods_num = number
				} else {
					if (number > item.max) {
						return;
					}
					item.goods_num = number
				}
			},
			toAddress(){
				_this.toNext(`/pages/my/address-list?is_cart=1`)
			},
			changePay(item){
				if (item.pay_code == _this.pay_code) {
					return
				}
				_this.pay_code = item.pay_code
			},
			switchChange(e){
				
			}
		},
		onLoad(e) {
			_this = this;
			let sysInfo = uni.getSystemInfoSync();
			_this.safe_bot = sysInfo.safeAreaInsets.bottom
			if (e) {
				for (let item in e) {
					_this[item] = e[item]
				}
			}
			_this.cart_tj()
			uni.$on('chooseAddress',res=>{
				_this.user_address = res
			})
		},
		onUnload() {
			uni.$off('chooseAddress')
		},
		computed: {
			total_num:{
				cache:false,
				get() {
					var total_num = 0
					if(this.lists.length>0){
						for (let i = 0; i < _this.lists.length; i++) {
							let item = this.lists[i]
							for (var j = 0; j < item.child.length; j++) {
								let child = item.child[j]
								total_num+=child.goods_num
							}
						}
					}
					return total_num
				}
			},
			total_amount:{
				cache:false,
				get() {
					var total_amount = 0
					if(this.goods.length>0){
						for (let i = 0; i < _this.goods.length; i++) {
							let item = this.goods[i]
							total_amount+=item.goods_num * item.goods_price
						}
					}
					return total_amount.toFixed(2)
				}
			},
		}
	}
</script>

